cat > /usr/ikuai/script/wg_dns_split.lua <<'WG_WAN_PATCH__usr_ikuai_script_wg_dns_split_lua'
#!/usr/bin/ikluajit

local Socket = require "iklua.ffi.socket"

local LISTEN_ADDR = "0.0.0.0"
local LISTEN_PORT = tonumber(os.getenv("WG_DNS_LISTEN_PORT") or "6053")
local CHINA_DNS = os.getenv("WG_DNS_CHINA_DNS") or "223.5.5.5"
local OVERSEA_DNS = os.getenv("WG_DNS_OVERSEA_DNS") or "1.1.1.1"
local DOMAIN_FILE = os.getenv("WG_DNS_DOMAIN_FILE") or "/etc/mnt/ikuai/wg_dns_split/china_domains.txt"

local china_domains = {}

local function load_domains()
    local file = io.open(DOMAIN_FILE, "r")
    if not file then
        return 0
    end

    local count = 0
    for line in file:lines() do
        local domain = line:lower():match("^%s*([%w%._%-]+)%s*$")
        if domain and domain:find("%.") then
            china_domains[domain] = true
            count = count + 1
        end
    end
    file:close()
    return count
end

local function query_name(packet)
    if #packet < 13 then
        return nil
    end

    local labels = {}
    local pos = 13
    while pos <= #packet do
        local len = packet:byte(pos)
        if not len or len == 0 then
            break
        end
        if len > 63 or pos + len > #packet then
            return nil
        end
        labels[#labels + 1] = packet:sub(pos + 1, pos + len):lower()
        pos = pos + len + 1
    end
    if #labels == 0 then
        return nil
    end
    return table.concat(labels, ".")
end

local function is_china_domain(domain)
    while domain do
        if china_domains[domain] then
            return true
        end
        domain = domain:match("^[^%.]+%.(.+)$")
    end
    return false
end

local function ask_upstream(packet, dns)
    local fd = Socket.UDP()
    if fd < 0 then
        return nil
    end
    Socket.SetTimeout(fd, 2)
    Socket.SendtoHost(fd, packet, dns, 53)
    local reply = Socket.Recvfrom(fd)
    Socket.sk_close(fd)
    return reply
end

local count = load_domains()
local server, err = Socket.UdpServer(LISTEN_ADDR, LISTEN_PORT)
if server < 0 then
    io.stderr:write("wg dns split bind failed: " .. tostring(err) .. "\n")
    os.exit(1)
end

local client_addr = Socket.MakeSockaddr("0.0.0.0", 0)
io.stdout:write("wg dns split listening port=" .. LISTEN_PORT .. " domains=" .. count .. "\n")
io.stdout:flush()

while true do
    local packet = Socket.Recvfrom(server, nil, nil, client_addr)
    if packet then
        local domain = query_name(packet)
        local china = is_china_domain(domain or "")
        local reply = ask_upstream(packet, china and CHINA_DNS or OVERSEA_DNS)
        if not reply and china then
            reply = ask_upstream(packet, OVERSEA_DNS)
        end
        io.stdout:write((domain or "invalid") .. " route=" .. (china and "china" or "oversea") .. " reply=" .. (reply and "yes" or "no") .. "\n")
        io.stdout:flush()
        if reply then
            Socket.Sendto(server, reply, client_addr)
        end
    end
end

