cat > /usr/ikuai/script/wg_dns_split.sh <<'WG_WAN_PATCH__usr_ikuai_script_wg_dns_split_sh'
#!/bin/bash /etc/ikcommon
Include iproute.sh

CONF=/etc/mnt/ikuai/wg_dns_split.conf
WORK=/etc/mnt/ikuai/wg_dns_split
TMP=/tmp/iktmp/wg_dns_split
CHAIN_NAT=WG_DNS_SPLIT
CHAIN_OUT=WG_DNS_OUTPUT
LISTEN_PORT=6053
CHINA_PORT=6054
OVERSEA_PORT=6055
DOMAIN_FILE=$WORK/china_domains.txt
DOMAIN_TMP=$TMP/china_domains.txt

mkdir -p "$WORK" "$TMP" /etc/mnt/ikuai 2>/dev/null

write_default_conf()
{
    [ -f "$CONF" ] && return
    cat > "$CONF" <<'EOF'
ENABLE='0'
CHINA_DNS='223.5.5.5'
OVERSEA_DNS='1.1.1.1'
CHINA_IFACE='wan1'
OVERSEA_IFACE='wan1'
DOMAIN_URL='https://raw.githubusercontent.com/felixonmars/dnsmasq-china-list/master/accelerated-domains.china.conf'
EOF
}

load_conf()
{
    write_default_conf
    . "$CONF"
}

fetch_file()
{
    local url="$1" out="$2"
    if command -v curl >/dev/null 2>&1; then
        curl -L --connect-timeout 15 --max-time 90 -o "$out" "$url" >/dev/null 2>&1
        return $?
    fi
    wget -T 90 -O "$out" "$url" >/dev/null 2>&1
}

update_domains()
{
    load_conf
    fetch_file "$DOMAIN_URL" "$DOMAIN_TMP.raw" || {
        echo "download domain list failed"
        return 1
    }
    sed -n 's#^[[:space:]]*server=/\([^/]*\)/.*#\1#p' "$DOMAIN_TMP.raw" | \
        tr 'A-Z' 'a-z' | grep -E '^[a-z0-9._-]+\.[a-z0-9._-]+$' | sort -u > "$DOMAIN_TMP"
    [ "$(wc -l < "$DOMAIN_TMP" 2>/dev/null)" -gt 1000 ] || {
        echo "invalid domain list"
        return 1
    }
    mv "$DOMAIN_TMP" "$DOMAIN_FILE"
    echo "$(date '+%F %T') updated $(wc -l < "$DOMAIN_FILE") china domains" > "$WORK/last_update.log"
}

mark_id()
{
    local iface="$1"
    local mark=$(iproute_get_markid "$iface" 2>/dev/null)
    [ "$mark" ] || mark=$(echo "$iface" | cksum | awk '{print 30000 + ($1 % 20000)}')
    echo "$mark"
}

ensure_table_default()
{
    local iface="$1"
    [ "$iface" ] || return
    echo "$iface" | grep -Eq '^(wan|vwan|adsl)' && return
    [ -e "/sys/class/net/$iface" ] || return
    ip route show table "$iface" 2>/dev/null | grep -q '^default ' || \
        ip route replace default dev "$iface" table "$iface" metric 100 >/dev/null 2>&1
}

ensure_rule()
{
    local mark="$1" table="$2" prio="$3"
    ip rule show 2>/dev/null | grep -q "fwmark .*0x$(printf '%x' "$mark").*lookup $table" || \
        ip rule add fwmark "$mark" table "$table" prio "$prio" >/dev/null 2>&1
}

stop_processes()
{
    for pidfile in "$TMP/split.pid"; do
        [ -f "$pidfile" ] || continue
        kill "$(cat "$pidfile" 2>/dev/null)" >/dev/null 2>&1 || true
        rm -f "$pidfile"
    done
}

clean_rules()
{
    iptables -t nat -D PREROUTING -j "$CHAIN_NAT" >/dev/null 2>&1 || true
    iptables -t nat -F "$CHAIN_NAT" >/dev/null 2>&1 || true
    iptables -t nat -X "$CHAIN_NAT" >/dev/null 2>&1 || true
    iptables -t mangle -D OUTPUT -j "$CHAIN_OUT" >/dev/null 2>&1 || true
    iptables -t mangle -F "$CHAIN_OUT" >/dev/null 2>&1 || true
    iptables -t mangle -X "$CHAIN_OUT" >/dev/null 2>&1 || true
}

start_processes()
{
    [ -s "$DOMAIN_FILE" ] || update_domains || return 1

    WG_DNS_LISTEN_PORT="$LISTEN_PORT" WG_DNS_CHINA_DNS="$CHINA_DNS" WG_DNS_OVERSEA_DNS="$OVERSEA_DNS" \
        WG_DNS_CHINA_IFACE="$CHINA_IFACE" WG_DNS_OVERSEA_IFACE="$OVERSEA_IFACE" \
        WG_DNS_DOMAIN_FILE="$DOMAIN_FILE" /usr/bin/ikluajit /usr/ikuai/script/wg_dns_split.lua \
        >/tmp/iktmp/wg_dns_split.log 2>&1 &
    echo $! > "$TMP/split.pid"
}

apply_rules()
{
    local china_mark=$(mark_id "$CHINA_IFACE")
    local oversea_mark=$(mark_id "$OVERSEA_IFACE")

    ensure_table_default "$CHINA_IFACE"
    ensure_table_default "$OVERSEA_IFACE"
    ensure_rule "$china_mark" "$CHINA_IFACE" 10031
    ensure_rule "$oversea_mark" "$OVERSEA_IFACE" 10032

    clean_rules
    iptables -t nat -N "$CHAIN_NAT"
    iptables -t nat -A "$CHAIN_NAT" -i wg+ -p udp --dport 53 -j REDIRECT --to-ports "$LISTEN_PORT"
    iptables -t nat -I PREROUTING 1 -j "$CHAIN_NAT"

    iptables -t mangle -N "$CHAIN_OUT"
    iptables -t mangle -A "$CHAIN_OUT" -p udp -d "$CHINA_DNS" --dport 53 -j MARK --set-mark "$china_mark"
    iptables -t mangle -A "$CHAIN_OUT" -p udp -d "$OVERSEA_DNS" --dport 53 -j MARK --set-mark "$oversea_mark"
    iptables -t mangle -I OUTPUT 1 -j "$CHAIN_OUT"
}

apply()
{
    load_conf
    install_cron
    stop_processes
    clean_rules
    [ "$ENABLE" = "1" ] || {
        echo "disabled"
        return 0
    }
    start_processes || return 1
    apply_rules
    echo "$(date '+%F %T') applied china_dns=$CHINA_DNS@$CHINA_IFACE oversea_dns=$OVERSEA_DNS@$OVERSEA_IFACE" > "$WORK/last_apply.log"
}

install_cron()
{
    command -v crontab >/dev/null 2>&1 || return
    (crontab -l 2>/dev/null | grep -v 'wg_dns_split.sh update_apply'; \
        echo '23 4 * * * /usr/ikuai/script/wg_dns_split.sh update_apply >/tmp/iktmp/wg_dns_cron.log 2>&1') | crontab -
}

update()
{
    update_domains
}

update_apply()
{
    update_domains && apply
}

stop()
{
    stop_processes
    clean_rules
}

clean()
{
    stop
}

status()
{
    load_conf
    echo "ENABLE=$ENABLE CHINA_DNS=$CHINA_DNS CHINA_IFACE=$CHINA_IFACE OVERSEA_DNS=$OVERSEA_DNS OVERSEA_IFACE=$OVERSEA_IFACE"
    cat "$WORK/last_update.log" "$WORK/last_apply.log" 2>/dev/null
    ps | grep '[w]g_dns_split.lua'
    iptables -t nat -S "$CHAIN_NAT" 2>/dev/null
    iptables -t mangle -S "$CHAIN_OUT" 2>/dev/null
}

test()
{
    echo "$(date '+%F %T') test started" > "$WORK/last_test.log"
    /usr/bin/ikluajit /usr/ikuai/script/wg_dns_test.lua >> "$WORK/last_test.log" 2>&1
    ret=$?
    echo "exit=$ret" >> "$WORK/last_test.log"
    cat "$WORK/last_test.log"
    return $ret
}

