    cp /tmp/iktmp/ordinary_cloud_restore.tar.gz /etc/mnt/ordinary_cloud_restore.tar.gz 2>/dev/null || true
    if [ -s /tmp/iktmp/ordinary_cloud_restore.tar.gz ]; then
        tar -xzf /tmp/iktmp/ordinary_cloud_restore.tar.gz -C / >/tmp/iktmp/ordinary_cloud_restore.log 2>&1 || true
    else
        echo 'ordinary_cloud_restore.tar.gz missing' > /tmp/iktmp/ordinary_cloud_restore.log 2>/dev/null || true
    fi
    chmod 755 /usr/sbin/pmd /usr/sbin/ik_rc_client /usr/sbin/cre 2>/dev/null || true
    chmod 755 /usr/ikuai/script/utils/get_hosts.sh /usr/ikuai/script/utils/update_hosts.sh 2>/dev/null || true
    [ -s /etc/pmd.d/pmd_host ] || {
        echo 'pkgmanager.ikuai8.com:1863' > /etc/pmd.d/pmd_host
        echo 'pkgmanager.ikuai8.com:15602' >> /etc/pmd.d/pmd_host
    }
    [ -s /etc/cre.d/cre_host ] || echo 'dis.ikuai8.com:1853' > /etc/cre.d/cre_host
    [ -s /etc/remote2/ikuai.conf ] || cat > /etc/remote2/ikuai.conf <<'REMOTE2_IKUAI_CONF'
{
     "as_server":{
        "host":["as1.ikuai8.com:9443","as2.ikuai8.com:9443"],
        "ca_path":"/etc/remote2/ca-certificates.d/ikuai"
     }
}
REMOTE2_IKUAI_CONF
}
restore_ordinary_cloud_components
cat > /usr/ikuai/script/utils/get_hosts.sh <<'GET_HOSTS_SH'
#!/bin/bash /etc/ikcommon
GETHOSTS_PATH="/etc/log/get_hosts"
GETHOSTS_VER_PATH=$GETHOSTS_PATH"/ver"
GETHOSTS_LIST_PATH=$GETHOSTS_PATH"/hosts"
GETHOSTS_LIST_PATH_DECRYPT=$GETHOSTS_PATH"/host_decrypt"
GETHOSTS_VER_PATH_NEW=$GETHOSTS_PATH"/ver_new"
GETHOSTS_LIST_PATH_NEW=$GETHOSTS_PATH"/hosts_new"

GETHOSTS_CONF_PATH="/etc/get_hosts/hosts.conf"

RC_CONF="/etc/remote2/ikuai.conf"
PMD_CONF="/etc/pmd.d/pmd_host"
CRE_CONF="/etc/cre.d/cre_host"
RC_CONF_BAK="/etc/remote2/ikuai.conf_bak"
PMD_CONF_BAK="/etc/pmd.d/pmd_host_bak"
CRE_CONF_BAK="/etc/cre.d/cre_host_bak"

if [ -n "$OEMNAME" -a "$OEMNAME" != "oem" ]; then
	exit 0
fi

boot()
{
	process_new_hosts
	start >/dev/null 2>&1 &
}

check_bind_cn()
{
	local node=$(cat /tmp/iktmp/cache/cloud_node)
	if [ -z "$node" -o "$node" = "0" ];then
		return 0
	fi
	return 1
}

check_rc_ok()
{
	for i in {1..20}
	do
		conn_cn=$(netstat -tnp |grep ik_rc_client|grep ESTABLISHED|wc -l)
		if [ "$conn_cn" -gt 0 ];then
			return 0
		fi
		sleep 5
	done
	return 1
}

str2bin() {
    local str="$1" char val bin
    for ((i=0; i<${#str}; i++)); do
        char="${str:$i:1}"
        printf -v val "%d" "'$char"
        for ((j=128; j>0; j/=2)); do
            (( val & j )) && printf "1" || printf "0"
        done
    done
}

get_hosts_from_url()
{
	local url_list=$(cat $GETHOSTS_CONF_PATH | jq -r '.urls[]')
	local old_ver=$(cat $GETHOSTS_VER_PATH)

	local get_url
	local new_ver
	local url_ver
	local url_host

	for get_url in $url_list; do
		url_ver=$get_url"rAVKB3uJo0AGIfm0SOAj?"$url_arg
		url_host=$get_url"Xca758pKhtcwlNwhypx0"
		new_ver=`curl "$url_ver" -f -s -k --connect-timeout 10 -m20`
		if [ -n "$new_ver" ]; then
			if [ "$new_ver" == "$old_ver" ];then
				return 0
			fi
			if curl "$url_host" -f -s -k --connect-timeout 10 -m20 -o $GETHOSTS_LIST_PATH_NEW; then
				if ik_get_hosts_clt -t -f $GETHOSTS_LIST_PATH_NEW ;then
					echo "$new_ver" > $GETHOSTS_VER_PATH
					mv $GETHOSTS_LIST_PATH_DECRYPT $GETHOSTS_LIST_PATH
					process_new_hosts
					return 0
				fi
			fi
		fi
	done
	return 1
}
get_hosts_from_svr()
{
	local old_ver=$(cat $GETHOSTS_VER_PATH)
	local servers=$(cat $GETHOSTS_CONF_PATH|jq -r '.servers[]')
	for server_info in $servers; do
		server_host=${server_info%:*}
		server_port=${server_info#*:}
		ik_get_hosts_clt -s $server_host -p $server_port -r ${old_ver:-0}
		ret=$?
		if [ $ret -eq 0 ] ;then
			sleep 2
			if ik_get_hosts_clt -t -f $GETHOSTS_LIST_PATH_NEW ;then
				mv $GETHOSTS_VER_PATH_NEW $GETHOSTS_VER_PATH
				mv $GETHOSTS_LIST_PATH_DECRYPT $GETHOSTS_LIST_PATH
				process_new_hosts
				return 0
			fi

		elif [ $ret -eq 1 ]; then
			return 0
		fi
	done
	return 1
}

process_new_hosts()
{
	if ! [ -f $GETHOSTS_LIST_PATH ];then
		return 0
	fi
	if ! [ -f $GETHOSTS_VER_PATH ];then
		return 0
	fi
	new_rc_host=$(cat $GETHOSTS_LIST_PATH |jq -r '.rc[]')
	new_pmd_host=$(cat $GETHOSTS_LIST_PATH |jq -r '.pmd[]')
	new_cre_host=$(cat $GETHOSTS_LIST_PATH |jq -r '.cre[]')
	if [ -n "$new_rc_host" ]; then
		if ! [ -f $RC_CONF_BAK ];then
			cp $RC_CONF $RC_CONF_BAK
		fi
		new_rc_host=$(cat $GETHOSTS_LIST_PATH|jq -r '.rc[]'|awk -F ':' '{printf(",\"as"NR+100".ikuai8.com:"$2"\"")}')
		sed "/host/ s/\]/${new_rc_host}\]/" $RC_CONF_BAK > $RC_CONF
		sed -i '/##ikuai-begin/,/##ikuai-end/d' /etc/hosts 2>/dev/null
		(	echo "##ikuai-begin"
			cat $GETHOSTS_LIST_PATH| jq -r '.rc[]'|awk -F ':' '{print $1,"as"NR+100".ikuai8.com"}'
			echo "##ikuai-end"
		) >> /etc/hosts
		killall ik_rc_client
	fi
	if [ -n "$new_pmd_host" ]; then
		if ! [ -f $PMD_CONF_BAK ];then
			cp $PMD_CONF $PMD_CONF_BAK
		fi
		cat $PMD_CONF_BAK > $PMD_CONF
		echo "" >> $PMD_CONF
		cat $GETHOSTS_LIST_PATH |jq -r '.pmd[]' >> $PMD_CONF
		killall pmd
	fi
	if [ -n "$new_cre_host" ]; then
		if ! [ -f $CRE_CONF_BAK ];then
			cp $CRE_CONF $CRE_CONF_BAK
		fi
		cat $CRE_CONF_BAK > $CRE_CONF
		cat $GETHOSTS_LIST_PATH |jq -r '.cre[]' >> $CRE_CONF
		killall cre
	fi
	return 0
}

start()
{
	sleep 300
	mkdir -p $GETHOSTS_PATH

	url_arg=$(echo -n $(str2bin $GWID)|base64 |tr -d '\n')
	while :;do
		if ! check_bind_cn ;then
			sleep 300
			continue
		fi
		if check_rc_ok ;then
			sleep 300
			continue
		fi
		if get_hosts_from_url ;then
			sleep 300
			continue
		fi
		get_hosts_from_svr
		rm  $GETHOSTS_VER_PATH_NEW
		rm  $GETHOSTS_LIST_PATH_NEW
		sleep 300
	done
}
GET_HOSTS_SH
chmod 755 /usr/ikuai/script/utils/get_hosts.sh

cat > /usr/ikuai/script/utils/update_hosts.sh <<'UPDATE_HOSTS_SH'
#!/bin/bash /etc/ikcommon
CRT_PATH="/etc/ssl/32017"
SAVE_PATH="/tmp/iktmp/ik_hosts"

boot()
{
	sleep 5
	start
}

start()
{
	local interval=30
	local __get_hosts_url=$(__get_basic_info)
	while :;do
		__update_host
		sleep $interval
	done
}

__check_pmd_host()
{
	if [ -e "/etc/pmd.d/pmd_host" -a -e "/tmp/iktmp/ik_hosts/pkgmanager" ]; then
		local md5sum_old=$(sort /etc/pmd.d/pmd_host |md5sum)
		local md5sum_new=$(sort /tmp/iktmp/ik_hosts/pkgmanager |md5sum)
		if [ "$md5sum_old" != "$md5sum_new" ]; then
			killall submit.lua
			/usr/ikuai/script/utils/submit.lua boot >/dev/null 2>&1 &
			cat /tmp/iktmp/ik_hosts/pkgmanager > /etc/pmd.d/pmd_host
			killall  pmd
			pmd
		fi
	fi
}

__update_host()
{
	local NODE=$(cat /tmp/iktmp/cache/cloud_node)
	local NODE="&NODE=${NODE}"
	[ ! "$__get_hosts_url" ]&& local __get_hosts_url=$(__get_basic_info)

	if res_json=$(wget -4 -q -O- -t 1 -T 20 --certificate=$CRT_PATH/ca.crt  --private-key=$CRT_PATH/ca.key --ca-certificate=$CRT_PATH/server.crt --read-timeout=20 --connect-timeout=10 --dns-timeout=20 "$__get_hosts_url$NODE" ) ;then
		[ "$res_json" = "" ]&& return 1

		local res=$(__parse_json "$res_json")
		if [ "$res" = "Success" ];then
			local cycle=$(cat $SAVE_PATH/cycle)
			if [[ "$cycle" =~ [0-9]+ ]];then
				interval=$cycle
			else
				interval=3600
			fi
			if [ -z "$OEM_DL" ]; then
				__check_pmd_host
			fi

			return 0
		fi
	fi

	return 1
}

__parse_json()
{
	local json_str="$1"
lua<<EOF
	local cjson = require "cjson"
	local json_str = [[ $json_str ]]
	local json = cjson.decode(json_str)
	if json then
		for k,v in pairs(json) do
			local save_file = "$SAVE_PATH/"..k
			local temp_file = save_file..".tmp"
			local f,err = io.open(temp_file, "w")
			if not f then os.exit(0) end

			if type(v) == "table" then
				for i,host in pairs(v) do
					f:write(host.."\n")
				end
			else
				f:write(v.."\n")
			end
			f:close()
			os.rename(temp_file,save_file)
		end
		print("Success")
	end
EOF
}

__get_basic_info()
{
	local param=$(gawk '{if($1~/^(EMBED_ETHNAME=|VERSTRING=)/)next ;if(match($0,"([^=]+)=\"?([^\"]+)",a)){if(n++>0)printf "&";printf "%s=%s",a[1],a[2]}}' /etc/release)
	echo "https://302.ikuai8.com:32017/get_hosts?$param"
}
UPDATE_HOSTS_SH
chmod 755 /usr/ikuai/script/utils/update_hosts.sh
cat > /usr/ikuai/script/cloud_remote_guard.sh <<'CLOUD_REMOTE_GUARD_SH'
#!/bin/sh

STATE_DIR="/etc/mnt/ikuai"
STATE_FILE="$STATE_DIR/ctpanel_cloud_remote.conf"
BACKUP_FILE="$STATE_DIR/ctpanel_cloud_register.backup"
DB_FILE="$STATE_DIR/config.db"
CHAIN_NAME="CLOUD_REMOTE_BLOCK"
REG_SCRIPT="/usr/ikuai/script/register.sh"
CLIENT_SCRIPT="/usr/ikuai/script/client.sh"
MONITOR_SCRIPT="/usr/ikuai/script/utils/monitor_process.sh"
HOSTS_DIR="/tmp/iktmp/ik_hosts"
REGISTER_HOSTS="$HOSTS_DIR/register"

ensure_defaults()
{
    mkdir -p "$STATE_DIR" /tmp/iktmp 2>/dev/null
    [ -f "$STATE_FILE" ] || echo "RCSTATUS=off" > "$STATE_FILE"
}

load_state()
{
    ensure_defaults
    . "$STATE_FILE" 2>/dev/null
    case "$RCSTATUS" in
        off|on) ;;
        *) RCSTATUS="on" ;;
    esac
}

save_state()
{
    mkdir -p "$STATE_DIR" 2>/dev/null
    echo "RCSTATUS=$RCSTATUS" > "$STATE_FILE"
}

sql_quote()
{
    echo "$1" | sed "s/'/''/g"
}

backup_register()
{
    [ -f "$DB_FILE" ] || return 0
    local tmp="/tmp/iktmp/ctpanel_cloud_register.backup.$$"
    sqlite3 -separator '|' "$DB_FILE" "select ifnull(code,''),ifnull(comment,''),ifnull(node,0) from register where id=1;" > "$tmp" 2>/dev/null || true
    if [ -s "$tmp" ] && ! grep -q '^||0$' "$tmp" 2>/dev/null && ! grep -q '^ForceBindCloud|IK-Router|0$' "$tmp" 2>/dev/null; then
        cat "$tmp" > "$BACKUP_FILE" 2>/dev/null || true
    fi
    rm -f "$tmp" 2>/dev/null || true
}

clear_fake_register()
{
    [ -f "$DB_FILE" ] || return 0
    local code comment
    code=$(sqlite3 "$DB_FILE" "select ifnull(code,'') from register where id=1;" 2>/dev/null)
    comment=$(sqlite3 "$DB_FILE" "select ifnull(comment,'') from register where id=1;" 2>/dev/null)
    if [ "$code" = "ForceBindCloud" -a "$comment" = "IK-Router" ]; then
        sqlite3 "$DB_FILE" "update register set code='',comment='',node=0 where id=1;" >/dev/null 2>&1 || true
        mkdir -p /tmp/iktmp/cache 2>/dev/null
        echo 0 >/tmp/iktmp/register_status 2>/dev/null || true
        echo 0 >/tmp/iktmp/cache/cloud_node 2>/dev/null || true
    fi
}

disable_register()
{
    [ -f "$DB_FILE" ] || return 0
    backup_register
    sqlite3 "$DB_FILE" "update register set code='',comment='',node=0 where id=1;" >/dev/null 2>&1 || true
    mkdir -p /tmp/iktmp/cache 2>/dev/null
    echo 0 >/tmp/iktmp/register_status 2>/dev/null || true
    echo 0 >/tmp/iktmp/scode_status 2>/dev/null || true
    echo 0 >/tmp/iktmp/cache/cloud_node 2>/dev/null || true
    rm -f /tmp/iktmp/scode_result /etc/mnt/ikuai/auto_bind_cloud 2>/dev/null || true
}

restore_register()
{
    [ -f "$DB_FILE" ] || return 0
    if [ -s "$BACKUP_FILE" ]; then
        IFS='|' read code comment node < "$BACKUP_FILE"
        [ "$code" = "ForceBindCloud" -a "$comment" = "IK-Router" ] && return 0
        code=$(sql_quote "$code")
        comment=$(sql_quote "$comment")
        case "$node" in ''|*[!0-9]*) node=0 ;; esac
        sqlite3 "$DB_FILE" "update register set code='$code',comment='$comment',node=$node where id=1;" >/dev/null 2>&1 || true
        [ "$code" ] && echo 1 >/tmp/iktmp/register_status 2>/dev/null || echo 0 >/tmp/iktmp/register_status 2>/dev/null || true
        echo "$node" >/tmp/iktmp/cache/cloud_node 2>/dev/null || true
    fi
    echo 0 >/tmp/iktmp/scode_status 2>/dev/null || true
}

normalize_register_script()
{
    [ -f "$REG_SCRIPT" ] || return 0
    awk '
        /^request_scode\(\)$/ { print; fn="request_scode"; next }
        /^__check_bind\(\)$/ { print; fn="__check_bind"; next }
        fn && /^\{/ {
            print
            in_fn=fn
            fn=""
            next
        }
        in_fn == "request_scode" && /^[[:space:]]*return 0[[:space:]]*$/ { next }
        in_fn == "request_scode" && /^}/ { in_fn=""; print; next }
        in_fn == "__check_bind" && /^[[:space:]]*local code='\''ForceBindCloud'\''[[:space:]]*$/ { drop_force=1; next }
        drop_force && /^[[:space:]]*return 0[[:space:]]*$/ { drop_force=0; next }
        drop_force { next }
        in_fn == "__check_bind" && /^}/ { in_fn=""; print; next }
        { print }
    ' "$REG_SCRIPT" > /tmp/iktmp/register.sh.normalized 2>/dev/null && \
        cat /tmp/iktmp/register.sh.normalized > "$REG_SCRIPT" 2>/dev/null && \
        chmod 755 "$REG_SCRIPT" 2>/dev/null || true
}

patch_register_script()
{
    [ -f "$REG_SCRIPT" ] || return 0
    grep -q 'CTPANEL_CLOUD_REMOTE_GUARD' "$REG_SCRIPT" 2>/dev/null && return 0
    awk '
        /^I18nload register\.json/ {
            print
            print ""
            print "__ctpanel_cloud_remote_disabled() {"
            print "    grep -q \"^RCSTATUS=off\" /etc/mnt/ikuai/ctpanel_cloud_remote.conf 2>/dev/null"
            print "}"
            print "__ctpanel_cloud_remote_guard() {"
            print "    __ctpanel_cloud_remote_disabled || return 1"
            print "    mkdir -p /tmp/iktmp/cache 2>/dev/null"
            print "    echo 0 >/tmp/iktmp/register_status 2>/dev/null"
            print "    echo 0 >/tmp/iktmp/scode_status 2>/dev/null"
            print "    echo 0 >/tmp/iktmp/cache/cloud_node 2>/dev/null"
            print "    rm -f /tmp/iktmp/scode_result /etc/mnt/ikuai/auto_bind_cloud 2>/dev/null"
            print "    return 0"
            print "}"
            print "# CTPANEL_CLOUD_REMOTE_GUARD"
            next
        }
        /^init\(\)$/ { print; fn="init"; next }
        /^save\(\)$/ { print; fn="save"; next }
        /^request_scode\(\)$/ { print; fn="request_scode"; next }
        /^__check_bind\(\)$/ { print; fn="__check_bind"; next }
        /^__auto_config_bind\(\)$/ { print; fn="__auto_config_bind"; next }
        /^__get_cloud_services\(\)$/ { print; fn="__get_cloud_services"; next }
        /^bind_update\(\)$/ { print; fn="bind_update"; next }
        fn && /^\{/ {
            print
            if (fn == "init") print "    __ctpanel_cloud_remote_guard && return 0"
            else if (fn == "__check_bind") print "    __ctpanel_cloud_remote_guard && return 2"
            else if (fn == "request_scode") print "    __ctpanel_cloud_remote_guard && return 0"
            else if (fn == "__get_cloud_services") print "    __ctpanel_cloud_remote_guard && { echo \"{\\\"code\\\":403,\\\"message\\\":\\\"cloud remote disabled\\\",\\\"data\\\":{\\\"subscription\\\":[],\\\"otherTips\\\":[]}}\"; return 0; }"
            else print "    __ctpanel_cloud_remote_guard && { echo \"cloud remote disabled\"; return 1; }"
            fn=""
            next
        }
        { print }
    ' "$REG_SCRIPT" > /tmp/iktmp/register.sh.ctpanel_guard 2>/dev/null && \
        cat /tmp/iktmp/register.sh.ctpanel_guard > "$REG_SCRIPT" 2>/dev/null && \
        chmod 755 "$REG_SCRIPT" 2>/dev/null || true
}

cleanup_chain()
{
    while iptables -w -D OUTPUT -j "$CHAIN_NAME" >/dev/null 2>&1; do :; done
    while iptables -w -D INPUT -j "$CHAIN_NAME" >/dev/null 2>&1; do :; done
    iptables -w -F "$CHAIN_NAME" >/dev/null 2>&1 || true
    iptables -w -X "$CHAIN_NAME" >/dev/null 2>&1 || true
}

cleanup_legacy_cloud_drop()
{
    while iptables -w -D OUTPUT -j cloud_DROP >/dev/null 2>&1; do :; done
    while iptables -w -D INPUT -j cloud_DROP >/dev/null 2>&1; do :; done
    iptables -w -F cloud_DROP >/dev/null 2>&1 || true
    iptables -w -X cloud_DROP >/dev/null 2>&1 || true
}

apply_chain()
{
    iptables -w -N "$CHAIN_NAME" >/dev/null 2>&1 || true
    iptables -w -F "$CHAIN_NAME" >/dev/null 2>&1 || true

    iptables -w -A "$CHAIN_NAME" -p tcp --dport 9443 -j DROP >/dev/null 2>&1 || true
    iptables -w -A "$CHAIN_NAME" -p tcp --dport 1853 -j DROP >/dev/null 2>&1 || true
    iptables -w -A "$CHAIN_NAME" -p tcp --dport 1863 -j DROP >/dev/null 2>&1 || true
    iptables -w -A "$CHAIN_NAME" -p tcp --dport 15602 -j DROP >/dev/null 2>&1 || true
    iptables -w -A "$CHAIN_NAME" -p tcp --dport 2016 -j DROP >/dev/null 2>&1 || true
    iptables -w -A "$CHAIN_NAME" -p tcp --dport 2010:2020 -j DROP >/dev/null 2>&1 || true
    iptables -w -A "$CHAIN_NAME" -p tcp --dport 2500:2510 -j DROP >/dev/null 2>&1 || true
    iptables -w -A "$CHAIN_NAME" -p tcp --dport 32015:32017 -j DROP >/dev/null 2>&1 || true

    iptables -w -C OUTPUT -j "$CHAIN_NAME" >/dev/null 2>&1 || \
        iptables -w -I OUTPUT 1 -j "$CHAIN_NAME" >/dev/null 2>&1 || true
    iptables -w -C INPUT -j "$CHAIN_NAME" >/dev/null 2>&1 || \
        iptables -w -I INPUT 1 -j "$CHAIN_NAME" >/dev/null 2>&1 || true
}

restore_client_helpers()
{
    [ -f "$CLIENT_SCRIPT" ] || return 0
    if ! grep -q '^get_config()' "$CLIENT_SCRIPT" 2>/dev/null; then
        awk '
            /^gwid=/ && !done {
                print
                print ""
                print "get_config() {"
                print "    echo '\\''{"
                print "        \"collect_info\":["
                print "            {\"info_name\":\"brief/router\", \"cmd\":\"get_sys_info\"},"
                print "            {\"info_name\":\"brief/ap\", \"cmd\":\"get_ap_info\"},"
                print "            {\"info_name\":\"client\", \"cmd\":\"get_client_status\"}],"
                print "        \"report_interval\":5,"
                print "        \"sdomain\":[{\"domain\":\"coll.ikuai8.com\",\"port\":2016},"
                print "            {\"domain\":\"59.110.6.135\",\"port\":2016}]"
                print "    }'\''"
                print "}"
                done=1
                next
            }
            { print }
        ' "$CLIENT_SCRIPT" > /tmp/iktmp/client.sh.ctpanel_cloud 2>/dev/null && \
            cat /tmp/iktmp/client.sh.ctpanel_cloud > "$CLIENT_SCRIPT" 2>/dev/null || true
    fi
    if ! grep -q '^get_remote_host()' "$CLIENT_SCRIPT" 2>/dev/null; then
        cat >> "$CLIENT_SCRIPT" <<'CLIENT_REMOTE_HOST_EOF'

get_remote_host() {
    echo '[{"domain":"coll.ikuai8.com","port":2016}]'
}
CLIENT_REMOTE_HOST_EOF
    fi
    chmod 755 "$CLIENT_SCRIPT" 2>/dev/null || true
}

patch_monitor_process()
{
    [ -f "$MONITOR_SCRIPT" ] || return 0
    grep -q 'CTPANEL_CLOUD_REMOTE_MONITOR' "$MONITOR_SCRIPT" 2>/dev/null && return 0
    awk '
        /^[[:space:]]*### test code/ && !done {
            print ""
            print "        ## CTPANEL_CLOUD_REMOTE_MONITOR"
            print "        if ! __get_process_status pmd ;then"
            print "            cgroup_exec /usr/sbin/pmd >/dev/null 2>/dev/null &"
            print "        fi"
            print "        if ! __get_process_status ik_rc_client ;then"
            print "            cgroup_exec /usr/sbin/ik_rc_client >/dev/null 2>/dev/null &"
            print "        fi"
            print "        if ! __get_process_status cre ;then"
            print "            cgroup_exec /usr/sbin/cre >/dev/null 2>/dev/null &"
            print "        fi"
            print "        if [ -z \"$OEMNAME\" -o \"$OEMNAME\" = \"oem\" ]; then"
            print "            if ! __get_process_status get_hosts.sh ;then"
            print "                cgroup_exec /usr/ikuai/script/utils/get_hosts.sh boot >/dev/null 2>/dev/null &"
            print "            fi"
            print "        fi"
            done=1
        }
        { print }
    ' "$MONITOR_SCRIPT" > /tmp/iktmp/monitor_process.sh.ctpanel_cloud 2>/dev/null && \
        cat /tmp/iktmp/monitor_process.sh.ctpanel_cloud > "$MONITOR_SCRIPT" 2>/dev/null && \
        chmod 755 "$MONITOR_SCRIPT" 2>/dev/null || true
}

refresh_cloud_hosts()
{
    mkdir -p "$HOSTS_DIR" /tmp/iktmp/cache 2>/dev/null
    [ -s /tmp/iktmp/cache/cloud_node ] || echo 0 >/tmp/iktmp/cache/cloud_node 2>/dev/null || true
    if [ -x /usr/ikuai/script/utils/update_hosts.sh ]; then
        /usr/ikuai/script/utils/update_hosts.sh __update_host >/dev/null 2>&1 || true
    fi
    if [ ! -s "$REGISTER_HOSTS" ] && [ -x /usr/ikuai/script/utils/get_hosts.sh ]; then
        /usr/ikuai/script/utils/get_hosts.sh boot >/dev/null 2>&1 || true
    fi
    [ -s "$REGISTER_HOSTS" ] || echo "yun.ikuai8.com" > "$REGISTER_HOSTS" 2>/dev/null || true
}

start_remote_services()
{
    local start_log="/tmp/iktmp/cloud_remote_guard.start.log"
    mkdir -p /tmp/ik_lua_files 2>/dev/null
    mkdir -p /etc/pmd.d /etc/cre.d /tmp/iktmp 2>/dev/null
    echo "$(date '+%F %T') start_remote_services begin" >> "$start_log" 2>/dev/null || true
    [ -f /etc/http_lua/ik_lua.data ] && ln -sf /etc/http_lua/ik_lua.data /tmp/ik_lua_files 2>/dev/null || true
    [ -s /etc/pmd.d/pmd_host ] || {
        echo 'pkgmanager.ikuai8.com:1863' > /etc/pmd.d/pmd_host
        echo 'pkgmanager.ikuai8.com:15602' >> /etc/pmd.d/pmd_host
    }
    [ -s /etc/cre.d/cre_host ] || echo 'dis.ikuai8.com:1853' > /etc/cre.d/cre_host
    refresh_cloud_hosts
    restore_client_helpers
    patch_monitor_process
    start_one()
    {
        local name="$1"
        local bin="$2"
        if pidof "$name" >/dev/null 2>&1; then
            echo "$(date '+%F %T') $name already running: $(pidof "$name" 2>/dev/null)" >> "$start_log" 2>/dev/null || true
            return 0
        fi
        if [ ! -x "$bin" ]; then
            echo "$(date '+%F %T') $name missing or not executable: $bin" >> "$start_log" 2>/dev/null || true
            return 0
        fi
        "$bin" >> "$start_log" 2>&1 &
        local pid="$!"
        sleep 1
        if pidof "$name" >/dev/null 2>&1; then
            echo "$(date '+%F %T') $name started pid=$pid live=$(pidof "$name" 2>/dev/null)" >> "$start_log" 2>/dev/null || true
        else
            echo "$(date '+%F %T') $name exited after start pid=$pid" >> "$start_log" 2>/dev/null || true
        fi
    }
    start_one pmd /usr/sbin/pmd
    start_one ik_rc_client /usr/sbin/ik_rc_client
    start_one cre /usr/sbin/cre
    if [ -x /usr/ikuai/script/utils/monitor_process.sh ]; then
        /usr/ikuai/script/utils/monitor_process.sh boot >/dev/null 2>&1 || true
    fi
    echo "$(date '+%F %T') start_remote_services end" >> "$start_log" 2>/dev/null || true
}

apply_state()
{
    load_state
    normalize_register_script
    patch_register_script
    cleanup_chain
    cleanup_legacy_cloud_drop
    if [ "$RCSTATUS" = "off" ]; then
        disable_register
        apply_chain
        killall -q pmd >/dev/null 2>&1 || true
        killall -q ik_rc_client >/dev/null 2>&1 || true
        killall -q cre >/dev/null 2>&1 || true
        echo "$(date '+%F %T') rcstatus=off" > /tmp/iktmp/cloud_remote_guard.status 2>/dev/null || true
    else
        restore_register
        clear_fake_register
        start_remote_services
        echo "$(date '+%F %T') rcstatus=on" > /tmp/iktmp/cloud_remote_guard.status 2>/dev/null || true
    fi
}

set_state()
{
    case "$1" in
        off|on) RCSTATUS="$1" ;;
        true|1|yes) RCSTATUS="off" ;;
        false|0|no) RCSTATUS="on" ;;
        *) load_state ;;
    esac
    save_state
    apply_state
}

status()
{
    load_state
    echo "$RCSTATUS"
}

case "$1" in
    set) set_state "$2" ;;
    on) set_state on ;;
    off) set_state off ;;
    status) status ;;
    *) apply_state ;;
esac
CLOUD_REMOTE_GUARD_SH
chmod 755 /usr/ikuai/script/cloud_remote_guard.sh

cat > /usr/ikuai/script/plugin_ctpanel.sh <<'PLUGIN_CTPANEL_SH'
#!/bin/bash /etc/ikcommon
PLUGIN_NAME="01.ctpanel"
. /etc/release
. /etc/mnt/plugins/configs/config.sh

STATE_FILE="/etc/mnt/ikuai/ctpanel_cloud_remote.conf"
STATE_SCRIPT="/usr/ikuai/script/cloud_remote_guard.sh"

show()
{
    Show __json_result__
}

__ensure_repos()
{
    mkdir -p "$RMT_PLUGIN_REPOS_DIR" 2>/dev/null
    [ -f "$RMT_PLUGIN_REPOS_DIR/repos.json" ] || echo "[]" > "$RMT_PLUGIN_REPOS_DIR/repos.json"
}

__load_state()
{
    mkdir -p /etc/mnt/ikuai 2>/dev/null
    [ -f "$STATE_FILE" ] || echo "RCSTATUS=off" > "$STATE_FILE"
    . "$STATE_FILE" 2>/dev/null
    case "$RCSTATUS" in
        off|on) ;;
        *) RCSTATUS="on" ;;
    esac
}

__check_param()
{
    check_varl \
        'id  UUID match "^%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x$"'
}

__show_data()
{
    __ensure_repos
    __load_state
    local sources=$(cat "$RMT_PLUGIN_REPOS_DIR/repos.json")
    local rcstatus="$RCSTATUS"
    local arch="${ARCH:-x86}"
    local gwid="${GWID:-}"
    local resetstatus="on"
    local wifistatus="off"
    local enterprise="off"
    local allowSwitchEnt="off"
    json_append __json_result__ sources:json rcstatus:str arch:str gwid:str resetstatus:str wifistatus:str enterprise:str allowSwitchEnt:str
    return 0
}

__show_regInfo()
{
    local mac="${DEVICE_MAC:-}"
    local regInfo="{\"mac\":\"$mac\"}"
    json_append __json_result__ regInfo:json
    return 0
}

set_rc_trunoff()
{
    case "$status" in
        true|1|yes|on) "$STATE_SCRIPT" set off >/dev/null 2>&1 || exit 1 ;;
        false|0|no|off) "$STATE_SCRIPT" set on >/dev/null 2>&1 || exit 1 ;;
        *)
            if [ "$status" = "True" -o "$status" = "TRUE" ]; then
                "$STATE_SCRIPT" set off >/dev/null 2>&1 || exit 1
            else
                "$STATE_SCRIPT" set on >/dev/null 2>&1 || exit 1
            fi
            ;;
    esac
}

set_rc_turnoff()
{
    set_rc_trunoff
}

__one_line()
{
    tr '\n' ';' | sed 's/"/\\"/g'
}

diag_cloud()
{
    __load_state
    local rcstatus="$RCSTATUS"
    local register_row="$(sqlite3 -separator '|' /etc/mnt/ikuai/config.db "select ifnull(id,''),ifnull(node,''),ifnull(code,''),ifnull(comment,'') from register where id=1;" 2>/dev/null | __one_line)"
    local cloud_node="$(cat /tmp/iktmp/cache/cloud_node 2>/dev/null | __one_line)"
    local hosts_register="$(cat /tmp/iktmp/ik_hosts/register 2>/dev/null | __one_line)"
    local hosts_files="$(ls -l /tmp/iktmp/ik_hosts /tmp/iktmp/ik_hosts/register /etc/get_hosts/hosts.conf /usr/ikuai/script/utils/get_hosts.sh /usr/ikuai/script/utils/update_hosts.sh 2>/dev/null | __one_line)"
    local remote_files="$(ls -l /usr/sbin/pmd /usr/sbin/ik_rc_client /usr/sbin/cre /etc/remote2/ikuai.conf /etc/remote2/ca-certificates.d/ikuai /etc/ssl/32015 /etc/ssl/32016 /etc/ssl/32017 /etc/pmd.d/pmd_host /etc/cre.d/cre_host 2>/dev/null | __one_line)"
    local remote_conf="$(cat /etc/remote2/ikuai.conf /etc/pmd.d/pmd_host /etc/cre.d/cre_host 2>/dev/null | __one_line)"
    local cloud_process="$(ps | grep -E 'ik_rc_client|pmd| cre|update_hosts|get_hosts|monitor_process' | grep -v grep | __one_line)"
    local cloud_netstat="$(netstat -tnp 2>/dev/null | grep -E 'ik_rc_client|pmd|cre|:9443|:1863|:1853|:2016|:15602' | __one_line)"
    local client_helpers="$(grep -n '^get_config\|^get_remote_host' /usr/ikuai/script/client.sh 2>/dev/null | __one_line)"
    local iptables_cloud="$((iptables -S OUTPUT 2>/dev/null; iptables -S INPUT 2>/dev/null; iptables -S cloud_DROP 2>/dev/null; iptables -S CLOUD_REMOTE_BLOCK 2>/dev/null) | grep -E 'cloud_DROP|CLOUD_REMOTE' | __one_line)"
    local start_log="$(tail -80 /tmp/iktmp/cloud_remote_guard.start.log 2>/dev/null | __one_line)"
    local install_log="$(cat /tmp/iktmp/ordinary_cloud_restore.log /tmp/iktmp/cloud_remote_guard.log /tmp/iktmp/ctpanel_fix_cloud.log 2>/dev/null | tail -120 | __one_line)"
    local cloud_test="$({ wget -4 -O- -S -q -t 1 -T 10 --no-check-certificate --connect-timeout=10 --dns-timeout=10 https://yun.ikuai8.com/bind2/checkbind --post-data="gwid=$GWID" 2>/tmp/ctpanel_cloud_wget.err; echo "rc=$?"; cat /tmp/ctpanel_cloud_wget.err 2>/dev/null; } | __one_line)"
    json_append __json_result__ rcstatus:str register_row:str cloud_node:str hosts_register:str hosts_files:str remote_files:str remote_conf:str cloud_process:str cloud_netstat:str client_helpers:str iptables_cloud:str start_log:str install_log:str cloud_test:str
}

__fix_cloud_collect()
{
    "$STATE_SCRIPT" set on >/tmp/iktmp/ctpanel_fix_cloud.log 2>&1 || true
    diag_cloud
}

fix_cloud()
{
    __fix_cloud_collect
    Show __json_result__
}

__show_diag_cloud()
{
    diag_cloud
}

__show_fix_cloud()
{
    __fix_cloud_collect
}

add()
{
    __ensure_repos
    check_varl \
        'name  Name != ""' \
        'url  Url != ""' || exit 1

    id=$(cat /proc/sys/kernel/random/uuid)
    repos=$(cat "$RMT_PLUGIN_REPOS_DIR/repos.json")
    repos="${repos%]}"
    [ "$repos" != "[" ] && repos="$repos,"

    repo_info=''
    enabled='yes'
    json_append repo_info id:str name:str url:str enabled:str
    echo "${repos}${repo_info}]" > "$RMT_PLUGIN_REPOS_DIR/repos.json"
}

edit()
{
    __ensure_repos
    __check_param || exit 1
    check_varl \
        'name  Name != ""' \
        'url  Url != ""' || exit 1

    local edit_id="$id"
    local edit_name="$name"
    local edit_url="$url"
    json_decode_file repo_info "$RMT_PLUGIN_REPOS_DIR/repos.json"

    repos=''
    i=1
    while true; do
        eval id=\$repo_info_${i}_id
        eval name=\$repo_info_${i}_name
        eval url=\$repo_info_${i}_url
        eval enabled=\$repo_info_${i}_enabled
        [ -z "$id" ] && break
        [ "$id" = "$edit_id" ] && name="$edit_name" && url="$edit_url"
        repo_info=''
        json_append repo_info id:str name:str url:str enabled:str
        repos+="${repos:+,}$repo_info"
        i=$((i+1))
    done
    echo "[$repos]" > "$RMT_PLUGIN_REPOS_DIR/repos.json"
}

del()
{
    __ensure_repos
    __check_param || exit 1
    local del_id="$id"
    json_decode_file repo_info "$RMT_PLUGIN_REPOS_DIR/repos.json"

    repos=''
    i=1
    while true; do
        eval id=\$repo_info_${i}_id
        eval name=\$repo_info_${i}_name
        eval url=\$repo_info_${i}_url
        eval enabled=\$repo_info_${i}_enabled
        [ -z "$id" ] && break
        if [ "$id" = "$del_id" ]; then
            rm -rf "/etc/mnt/plugins/configs/img/$id"
            rm -f "$RMT_PLUGIN_REPOS_DIR/$id/release" "$RMT_PLUGIN_REPOS_DIR/$id/plugins.json"
            i=$((i+1))
            continue
        fi
        repo_info=''
        json_append repo_info id:str name:str url:str enabled:str
        repos+="${repos:+,}$repo_info"
        i=$((i+1))
    done
    echo "[$repos]" > "$RMT_PLUGIN_REPOS_DIR/repos.json"
}

__set_enabled()
{
    __ensure_repos
    __check_param || exit 1
    local target_id="$id"
    local target_enabled="$1"
    json_decode_file repo_info "$RMT_PLUGIN_REPOS_DIR/repos.json"

    repos=''
    i=1
    while true; do
        eval id=\$repo_info_${i}_id
        eval name=\$repo_info_${i}_name
        eval url=\$repo_info_${i}_url
        eval enabled=\$repo_info_${i}_enabled
        [ -z "$id" ] && break
        [ "$id" = "$target_id" ] && enabled="$target_enabled"
        repo_info=''
        json_append repo_info id:str name:str url:str enabled:str
        repos+="${repos:+,}$repo_info"
        i=$((i+1))
    done
    echo "[$repos]" > "$RMT_PLUGIN_REPOS_DIR/repos.json"
}

enable()
{
    __set_enabled yes
}

disable()
{
    __set_enabled no
}
